int git_pkt_parse(git_pkt **out, const char *line, size_t len) {
    git_pkt_ng *pkt;
    char *ref, *msg;
    const char *start;

    if (!line || len == 0 || len > INT_MAX) {
        return -1;
    }

    pkt = calloc(1, sizeof(git_pkt_ng));
    if (!pkt) {
        return -1;
    }

    start = line;
    pkt->ref_len = 0;
    while (pkt->ref_len < len && *start && *start != '\n') {
        pkt->ref_len++;
        start++;
    }

    if (pkt->ref_len == 0 || pkt->ref_len >= len) {
        free(pkt);
        return -1;
    }

    ref = strndup(line, pkt->ref_len);
    if (!ref) {
        free(pkt);
        return -1;
    }

    pkt->ref = ref;

    start++;
    pkt->msg_len = len - pkt->ref_len - 1;
    if (pkt->msg_len > 0) {
        msg = strndup(start, pkt->msg_len);
        if (!msg) {
            free(pkt->ref);
            free(pkt);
            return -1;
        }
        pkt->msg = msg;
    } else {
        pkt->msg = NULL;
    }

    *out = (git_pkt *)pkt;
    return 0;
}

