#include <stdlib.h>
#include <string.h>

typedef struct git_pkt {
    char *ref;
    char *msg;
} git_pkt;

typedef struct git_pkt_ng {
    char *ref;
    char *msg;
} git_pkt_ng;

int git_pkt_parse_network_packet(git_pkt **out, const char *line, size_t len) {
    git_pkt_ng *pkt;
    char *ref = NULL;
    char *msg = NULL;
    const char *start = line;
    const char *end = line + len;

    if (len < 4) {
        return -1;
    }

    pkt = (git_pkt_ng *)malloc(sizeof(git_pkt_ng));
    if (!pkt) {
        return -1;
    }

    if (memcmp(start, "ref ", 4) != 0) {
        free(pkt);
        return -1;
    }

    start += 4;
    if (start >= end) {
        free(pkt);
        return -1;
    }

    pkt->ref = (char *)malloc(end - start + 1);
    if (!pkt->ref) {
        free(pkt);
        return -1;
    }

    memcpy(pkt->ref, start, end - start);
    pkt->ref[end - start] = '\0';

    if (memcmp(pkt->ref, "capabilities^", 13) == 0) {
        free(pkt->ref);
        free(pkt);
        return -1;
    }

    pkt->msg = (char *)malloc(1);
    if (!pkt->msg) {
        free(pkt->ref);
        free(pkt);
        return -1;
    }

    pkt->msg[0] = '\0';

    *out = (git_pkt *)pkt;
    return 0;
}
